package local.generalsmc.nativebridge;

import net.minecraft.core.HolderLookup;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.saveddata.SavedData;

/** World-owned settings: every commander uses the server's choices, never a client preference. */
public final class WorldRules extends SavedData {
    public record Emp(boolean vehicles,boolean mobs,boolean redstone){public static Emp defaults(){return new Emp(true,true,true);}}
    public record Options(int startingCash,boolean limitSuperweapons,boolean microwaveMobs,boolean ecmArrows){public static Options defaults(){return new Options(10000,false,true,true);}}
    public record Values(boolean blockDestruction,boolean fireSpread,boolean hostileMobs,boolean neutralRetaliation,boolean environmentDamage,boolean naturalResources,int blastRadius,int blastPower,boolean mobGeneralExperience,boolean eliminationVictory,boolean forceAttackDestruction,boolean prepareStarts,Emp emp,Options options){
        public Values{if(emp==null)emp=Emp.defaults();if(options==null)options=Options.defaults();}
        public Values(boolean a,boolean b,boolean c,boolean d,boolean e,boolean f,int r,int p,boolean xp,boolean victory,boolean force,boolean prepare,Emp emp){this(a,b,c,d,e,f,r,p,xp,victory,force,prepare,emp,Options.defaults());}
        public Values withOptions(Options o){return new Values(blockDestruction,fireSpread,hostileMobs,neutralRetaliation,environmentDamage,naturalResources,blastRadius,blastPower,mobGeneralExperience,eliminationVictory,forceAttackDestruction,prepareStarts,emp,o);}
        public Values(boolean a,boolean b,boolean c,boolean d,boolean e,boolean f,int r,int p,boolean xp,boolean victory,boolean force,boolean prepare){this(a,b,c,d,e,f,r,p,xp,victory,force,prepare,Emp.defaults());}
        public Values(boolean a,boolean b,boolean c,boolean d,boolean e,boolean f,int radius,int power,boolean experience,boolean victory){this(a,b,c,d,e,f,radius,power,experience,victory,true,false);}
        public boolean affectsTerrain(boolean forced){return blockDestruction&&(!forceAttackDestruction||forced);}
        public Values(boolean a,boolean b,boolean c,boolean d,boolean e,boolean f,int radius,int power){this(a,b,c,d,e,f,radius,power,true,true);}
        public Values(boolean a,boolean b,boolean c,boolean d,boolean e,boolean f){this(a,b,c,d,e,f,2,1);}
        public static Values defaults(){return new Values(true,true,true,true,true,true);}
        public Values toggle(String key){return switch(key){
            case "blockDestruction"->new Values(!blockDestruction||forceAttackDestruction,fireSpread,hostileMobs,neutralRetaliation,environmentDamage,naturalResources,blastRadius,blastPower,mobGeneralExperience,eliminationVictory,!blockDestruction,prepareStarts,emp,options);
            case "prepareStarts"->new Values(blockDestruction,fireSpread,hostileMobs,neutralRetaliation,environmentDamage,naturalResources,blastRadius,blastPower,mobGeneralExperience,eliminationVictory,forceAttackDestruction,!prepareStarts,emp,options);
            case "fireSpread"->new Values(blockDestruction,!fireSpread,hostileMobs,neutralRetaliation,environmentDamage,naturalResources,blastRadius,blastPower,mobGeneralExperience,eliminationVictory,forceAttackDestruction,prepareStarts,emp,options);
            case "hostileMobs"->new Values(blockDestruction,fireSpread,!hostileMobs,neutralRetaliation,environmentDamage,naturalResources,blastRadius,blastPower,mobGeneralExperience,eliminationVictory,forceAttackDestruction,prepareStarts,emp,options);
            case "neutralRetaliation"->new Values(blockDestruction,fireSpread,hostileMobs,!neutralRetaliation,environmentDamage,naturalResources,blastRadius,blastPower,mobGeneralExperience,eliminationVictory,forceAttackDestruction,prepareStarts,emp,options);
            case "environmentDamage"->new Values(blockDestruction,fireSpread,hostileMobs,neutralRetaliation,!environmentDamage,naturalResources,blastRadius,blastPower,mobGeneralExperience,eliminationVictory,forceAttackDestruction,prepareStarts,emp,options);
            case "naturalResources"->new Values(blockDestruction,fireSpread,hostileMobs,neutralRetaliation,environmentDamage,!naturalResources,blastRadius,blastPower,mobGeneralExperience,eliminationVictory,forceAttackDestruction,prepareStarts,emp,options);
            case "blastRadius"->new Values(blockDestruction,fireSpread,hostileMobs,neutralRetaliation,environmentDamage,naturalResources,blastRadius%4+1,blastPower,mobGeneralExperience,eliminationVictory,forceAttackDestruction,prepareStarts,emp,options);
            case "blastPower"->new Values(blockDestruction,fireSpread,hostileMobs,neutralRetaliation,environmentDamage,naturalResources,blastRadius,blastPower%4+1,mobGeneralExperience,eliminationVictory,forceAttackDestruction,prepareStarts,emp,options);
            case "mobGeneralExperience"->new Values(blockDestruction,fireSpread,hostileMobs,neutralRetaliation,environmentDamage,naturalResources,blastRadius,blastPower,!mobGeneralExperience,eliminationVictory,forceAttackDestruction,prepareStarts,emp,options);
            case "eliminationVictory"->new Values(blockDestruction,fireSpread,hostileMobs,neutralRetaliation,environmentDamage,naturalResources,blastRadius,blastPower,mobGeneralExperience,!eliminationVictory,forceAttackDestruction,prepareStarts,emp,options);
            case "empVehicles"->new Values(blockDestruction,fireSpread,hostileMobs,neutralRetaliation,environmentDamage,naturalResources,blastRadius,blastPower,mobGeneralExperience,eliminationVictory,forceAttackDestruction,prepareStarts,new Emp(!emp.vehicles(),emp.mobs(),emp.redstone()),options);
            case "empMobs"->new Values(blockDestruction,fireSpread,hostileMobs,neutralRetaliation,environmentDamage,naturalResources,blastRadius,blastPower,mobGeneralExperience,eliminationVictory,forceAttackDestruction,prepareStarts,new Emp(emp.vehicles(),!emp.mobs(),emp.redstone()),options);
            case "empRedstone"->new Values(blockDestruction,fireSpread,hostileMobs,neutralRetaliation,environmentDamage,naturalResources,blastRadius,blastPower,mobGeneralExperience,eliminationVictory,forceAttackDestruction,prepareStarts,new Emp(emp.vehicles(),emp.mobs(),!emp.redstone()),options);
            case "microwaveMobs"->new Values(blockDestruction,fireSpread,hostileMobs,neutralRetaliation,environmentDamage,naturalResources,blastRadius,blastPower,mobGeneralExperience,eliminationVictory,forceAttackDestruction,prepareStarts,emp,new Options(options.startingCash(),options.limitSuperweapons(),!options.microwaveMobs(),options.ecmArrows()));
            case "ecmArrows"->new Values(blockDestruction,fireSpread,hostileMobs,neutralRetaliation,environmentDamage,naturalResources,blastRadius,blastPower,mobGeneralExperience,eliminationVictory,forceAttackDestruction,prepareStarts,emp,new Options(options.startingCash(),options.limitSuperweapons(),options.microwaveMobs(),!options.ecmArrows()));
            default->throw new IllegalArgumentException(local.generalsmc.LocalText.token("Неизвестная настройка"));};}
    }
    private volatile Values values=Values.defaults();
    private static final net.minecraft.world.level.saveddata.SavedDataType<WorldRules> FACTORY=new net.minecraft.world.level.saveddata.SavedDataType<>("generals_rules",WorldRules::new,CompoundTag.CODEC.xmap(WorldRules::load,value->value.save(new CompoundTag(),null)),null);
    public static WorldRules get(ServerLevel level){return level.getDataStorage().computeIfAbsent(FACTORY);}
    public Values values(){return values;}
    public void update(Values next){if(!next.equals(values)){values=next;setDirty();}}
    public static WorldRules load(CompoundTag tag){var rules=new WorldRules();var d=Values.defaults();rules.values=new Values(read(tag,"blockDestruction",d.blockDestruction),read(tag,"fireSpread",d.fireSpread),read(tag,"hostileMobs",d.hostileMobs),read(tag,"neutralRetaliation",d.neutralRetaliation),read(tag,"environmentDamage",d.environmentDamage),read(tag,"naturalResources",d.naturalResources),tag.contains("blastRadius")?Math.clamp(tag.getIntOr("blastRadius",0),1,4):d.blastRadius,tag.contains("blastPower")?Math.clamp(tag.getIntOr("blastPower",0),1,4):d.blastPower,read(tag,"mobGeneralExperience",d.mobGeneralExperience),read(tag,"eliminationVictory",d.eliminationVictory),read(tag,"forceAttackDestruction",true),read(tag,"prepareStarts",false),new Emp(read(tag,"empVehicles",true),read(tag,"empMobs",true),read(tag,"empRedstone",true)),new Options(tag.contains("startingCash")?Math.clamp(tag.getIntOr("startingCash",10000),1000,50000):10000,read(tag,"limitSuperweapons",false),read(tag,"microwaveMobs",true),read(tag,"ecmArrows",true)));return rules;}
    private static boolean read(CompoundTag tag,String key,boolean fallback){return tag.contains(key)?tag.getBooleanOr(key,false):fallback;}
    public CompoundTag save(CompoundTag tag,HolderLookup.Provider lookup){var v=values;tag.putBoolean("blockDestruction",v.blockDestruction);tag.putBoolean("fireSpread",v.fireSpread);tag.putBoolean("hostileMobs",v.hostileMobs);tag.putBoolean("neutralRetaliation",v.neutralRetaliation);tag.putBoolean("environmentDamage",v.environmentDamage);tag.putBoolean("naturalResources",v.naturalResources);tag.putInt("blastRadius",v.blastRadius);tag.putInt("blastPower",v.blastPower);tag.putBoolean("mobGeneralExperience",v.mobGeneralExperience);tag.putBoolean("eliminationVictory",v.eliminationVictory);tag.putBoolean("forceAttackDestruction",v.forceAttackDestruction);tag.putBoolean("prepareStarts",v.prepareStarts);tag.putBoolean("empVehicles",v.emp.vehicles());tag.putBoolean("empMobs",v.emp.mobs());tag.putBoolean("empRedstone",v.emp.redstone());tag.putInt("startingCash",v.options.startingCash());tag.putBoolean("limitSuperweapons",v.options.limitSuperweapons());tag.putBoolean("microwaveMobs",v.options.microwaveMobs());tag.putBoolean("ecmArrows",v.options.ecmArrows());return tag;}
}
